package com.smartresponse.domain;
import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="role_applications") public class RoleApplication {
 @Id @GeneratedValue private UUID id; @ManyToOne(optional=false) @JoinColumn(name="user_id") private AppUser user; @Enumerated(EnumType.STRING) private Role requestedRole; @Column(length=150) private String organisationName; @Column(length=32) private String professionalIdMasked; @JdbcTypeCode(SqlTypes.JSON) private String detailsJson; @Column(length=24) private String reviewStatus="PENDING"; private Instant submittedAt=Instant.now(); private Instant reviewedAt; @ManyToOne @JoinColumn(name="reviewed_by") private AppUser reviewedBy; @Column(length=1000) private String reviewNotes;
 protected RoleApplication(){} public RoleApplication(AppUser u,Role r,String org,String id,String details){user=u;requestedRole=r;organisationName=org;professionalIdMasked=id;detailsJson=details;} public UUID getId(){return id;} public String getReviewStatus(){return reviewStatus;} public Role getRequestedRole(){return requestedRole;} public String getOrganisationName(){return organisationName;} public Instant getSubmittedAt(){return submittedAt;} public AppUser getUser(){return user;} public void review(AppUser admin,boolean approved,String note){reviewedBy=admin;reviewStatus=approved?"APPROVED":"REJECTED";reviewNotes=note;reviewedAt=Instant.now();}
}
